/* Project-local Bootstrap 3 behavior compatibility layer.
 * Implements only the modal, tab, dropdown, and alert behaviors used here.
 * It intentionally does not parse arbitrary data-* configuration values.
 */
(function ($) {
  "use strict";

  if (!$ || !$.fn) return;

  function trigger($element, name) {
    var event = $.Event(name);
    $element.trigger(event);
    return !event.isDefaultPrevented();
  }

  function removeBackdrop() {
    $(".modal-backdrop").remove();
    if (!$(".modal.in:visible").length) $(document.body).removeClass("modal-open");
  }

  function showModal($modal, options) {
    if ($modal.hasClass("in") || !trigger($modal, "show.bs.modal")) return;
    var settings = $.extend({ backdrop: true, keyboard: true }, options || {});
    $modal.data("safe.modal.options", settings);
    if (settings.backdrop !== false) {
      removeBackdrop();
      $("<div class=\"modal-backdrop fade in\" aria-hidden=\"true\"></div>").appendTo(document.body);
    }
    $(document.body).addClass("modal-open");
    $modal.attr({ "aria-hidden": "false", "aria-modal": "true" }).css("display", "block").addClass("in");
    trigger($modal, "shown.bs.modal");
  }

  function hideModal($modal) {
    if (!$modal.hasClass("in") || !trigger($modal, "hide.bs.modal")) return;
    $modal.removeClass("in").attr({ "aria-hidden": "true", "aria-modal": null }).css("display", "none");
    removeBackdrop();
    trigger($modal, "hidden.bs.modal");
  }

  $.fn.modal = function (option) {
    return this.each(function () {
      var $modal = $(this);
      if (option === "hide") hideModal($modal);
      else if (option === "toggle") ($modal.hasClass("in") ? hideModal : showModal)($modal);
      else showModal($modal, typeof option === "object" ? option : {});
    });
  };

  function safeTabTarget($link) {
    var target = String($link.attr("href") || "");
    return /^#[A-Za-z][A-Za-z0-9_.:-]*$/.test(target) ? target : "";
  }

  $.fn.tab = function (action) {
    if (action && action !== "show") return this;
    return this.each(function () {
      var $link = $(this);
      var target = safeTabTarget($link);
      if (!target || !trigger($link, "show.bs.tab")) return;
      var $list = $link.closest("ul");
      $list.children("li").removeClass("active").children("a").attr("aria-expanded", "false");
      $link.closest("li").addClass("active");
      $link.attr("aria-expanded", "true");
      var $content = $list.nextAll(".tab-content").first();
      $content.children(".tab-pane").removeClass("active in").attr("aria-hidden", "true");
      $content.children(target).addClass("active in").attr("aria-hidden", "false");
      trigger($link, "shown.bs.tab");
    });
  };

  function closeDropdowns(except) {
    $(".dropdown.open").each(function () {
      if (except && this === except) return;
      $(this).removeClass("open").children("[data-toggle=\"dropdown\"]").attr("aria-expanded", "false");
    });
  }

  $(document)
    .on("click.safeBootstrap", "[data-toggle=\"tab\"]", function (event) {
      event.preventDefault();
      $(this).tab("show");
    })
    .on("click.safeBootstrap", "[data-toggle=\"dropdown\"]", function (event) {
      event.preventDefault();
      event.stopPropagation();
      var parent = $(this).closest(".dropdown")[0];
      var shouldOpen = parent && !$(parent).hasClass("open");
      closeDropdowns(parent);
      if (parent) {
        $(parent).toggleClass("open", shouldOpen);
        $(this).attr("aria-expanded", shouldOpen ? "true" : "false");
      }
    })
    .on("click.safeBootstrap", "[data-dismiss=\"modal\"]", function (event) {
      event.preventDefault();
      hideModal($(this).closest(".modal"));
    })
    .on("click.safeBootstrap", "[data-dismiss=\"alert\"]", function (event) {
      event.preventDefault();
      var $alert = $(this).closest(".alert");
      if (trigger($alert, "close.bs.alert")) $alert.remove();
    })
    .on("click.safeBootstrap", function () { closeDropdowns(); })
    .on("keydown.safeBootstrap", function (event) {
      if (event.key === "Escape") {
        closeDropdowns();
        $(".modal.in").each(function () {
          var $modal = $(this);
          if (($modal.data("safe.modal.options") || {}).keyboard !== false) hideModal($modal);
        });
      }
    });
})(window.jQuery);
